def t(key, tag='span', attrs=''):
    return f'<{tag} data-i18n="{key}" {attrs}>{en[key]}</{tag}>'
# A native vector print composition, static like the reference's hero plate.
lines=''.join(f'<path d="M{80+i*3} {130+i*5} L{245+i*2} {210+i*4} L{410+i*2} {125+i*5}"/>' for i in range(24))
plate=f'''<svg viewBox="0 0 600 510" role="img" aria-label="An open book drawn as a monochrome print"><defs><pattern id="dots" width="5" height="5" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".65" fill="currentColor"/></pattern></defs><rect width="600" height="510" fill="url(#dots)" opacity=".25"/><g fill="none" stroke="currentColor" stroke-width="1.5" transform="rotate(-12 300 255)">{lines}<path d="M80 130L245 210L410 125L490 355L310 450L150 360Z" stroke-width="3"/><path d="M245 210L310 450" stroke-width="3"/></g><text x="36" y="470" fill="currentColor" font-family="serif" font-size="22">Ex libris. Ex animo.</text></svg>'''
css='''
/* Cyrillic substitutions and geometry adapted to the reference masthead. */
:root{--ui:'Inter',sans-serif;--serif:'Source Serif 4',serif;--condensed:'Oswald',sans-serif;--masthead-size:clamp(150px,16.2vw,240px);--rail-duration:20s}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--color-paper);color:var(--color-headline-ink);font:var(--text-body)/var(--leading-body) var(--ui);letter-spacing:var(--tracking-body)}a{color:inherit;text-decoration:none}button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}a:hover{text-decoration:underline}button:hover{text-decoration:underline}:focus-visible{outline:2px solid currentColor;outline-offset:5px}h1,h2,p{margin:0}.rail{overflow:hidden;border-bottom:1px solid currentColor;padding:var(--spacing-8) 0;font:var(--text-heading-sm)/1.2 var(--serif)}.rail-track{display:flex;width:max-content;animation:marquee var(--rail-duration) linear infinite}.rail-copy{flex-shrink:0;padding-right:var(--spacing-32)}@keyframes marquee{to{transform:translateX(-50%)}}.motion-paused .rail-track{animation-play-state:paused}.topline{display:flex;justify-content:space-between;padding:var(--spacing-12) var(--spacing-16);text-transform:uppercase;font-size:var(--text-caption)}.languages{display:flex;gap:var(--spacing-8)}[aria-pressed=true]{text-decoration:underline;text-underline-offset:4px}.masthead{padding:0 var(--spacing-16)}h1{font:700 var(--masthead-size)/1.02 var(--condensed);letter-spacing:-.055em;white-space:nowrap;text-align:center;padding-top:var(--spacing-24);padding-bottom:var(--spacing-12);border-bottom:1px solid currentColor}.hero-bottom{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(0,1fr);gap:var(--spacing-16);padding-bottom:var(--spacing-32)}.subtitle{font:400 clamp(48px,5.5vw,84px)/1.1 var(--serif);letter-spacing:-.04em;border-bottom:1px solid currentColor;padding:var(--spacing-12) 0 var(--spacing-20);white-space:nowrap}.meta{font-size:var(--text-caption);border-bottom:1px solid currentColor;padding:var(--spacing-8) 0}.hero-columns{display:grid;grid-template-columns:1fr 1.2fr;gap:var(--spacing-32);padding-top:var(--spacing-24)}nav a{display:block;margin-bottom:var(--spacing-12);font-size:var(--text-body)}.intro{font:var(--text-heading-sm)/var(--leading-heading-sm) var(--serif);max-width:360px}.plate{border:1px solid currentColor;margin-top:var(--spacing-12);overflow:hidden;border-radius:var(--radius-cards)}.plate svg{display:block;width:100%;height:360px}.plate figcaption{padding:var(--spacing-8);border-top:1px solid currentColor;font-size:var(--text-caption)}figure{margin:0}.letter{padding:var(--spacing-80) var(--spacing-32);background:var(--color-headline-ink);color:var(--color-paper);text-align:center}.eyebrow{font-size:var(--text-caption);text-transform:uppercase}.letter h2{font:var(--text-heading-lg)/1.05 var(--serif);margin:var(--spacing-32) auto}.letter p{max-width:720px;margin:auto;font:var(--text-heading-sm)/1.4 var(--serif)}.program{padding:var(--spacing-64) var(--spacing-32)}.program-head{display:flex;align-items:baseline;justify-content:space-between;border-bottom:1px solid currentColor;padding-bottom:var(--spacing-24)}.program h2{font:700 90px/1 var(--condensed);letter-spacing:-.04em}.program-head p{font-family:var(--serif);font-style:italic;font-size:var(--text-heading-sm)}.event{display:grid;grid-template-columns:150px 1fr 1fr;gap:var(--spacing-32);padding:var(--spacing-32) 0;border-bottom:1px solid currentColor}.event h3{margin:0;font:var(--text-heading)/1.1 var(--serif)}.event p{max-width:480px}.event time{font-size:var(--text-caption)}.visit{padding:var(--spacing-64) var(--spacing-32);display:grid;grid-template-columns:1.5fr 1fr;border-top:1px solid currentColor;gap:var(--spacing-64)}.visit h2{font:var(--text-heading-lg)/1.05 var(--serif);letter-spacing:-.04em}.visit p{max-width:420px}.download{display:inline-block;border:1px solid currentColor;border-radius:var(--radius-buttons);padding:var(--spacing-12) var(--spacing-24);margin-top:var(--spacing-32)}footer{display:flex;justify-content:space-between;align-items:center;background:var(--color-headline-ink);color:var(--color-paper);padding:var(--spacing-20) var(--spacing-32);font-size:var(--text-caption)}html[data-lang=ru]{--masthead-size:clamp(130px,14vw,210px)}html[data-lang=ru] .subtitle{font-size:68px}html[data-lang=ru] .visit h2{font-size:64px}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.rail-track{animation:none}}
'''
body=f'''<div class="rail"><div class="rail-track"><span class="rail-copy">{t('rail')}</span><span class="rail-copy" aria-hidden="true">{t('rail')}</span></div></div>
<header class="topline"><b>MARGINALIA®</b>{t('date')}<div class="languages"><button data-lang="en" aria-pressed="true">EN</button><span>/</span><button data-lang="ru" aria-pressed="false">RU</button></div></header>
<main><section class="masthead">{t('title','h1')}<div class="hero-bottom"><div>{t('subtitle','div','class="subtitle"')}{t('meta','div','class="meta"')}<div class="hero-columns"><nav>{t('nav1','a','href="#programme"')}{t('nav2','a','href="#letter"')}{t('nav3','a','href="#visit"')}</nav><div>{t('eyebrow','p','class="eyebrow"')}{t('intro','p','class="intro"')}</div></div></div><figure class="plate">{plate}{t('caption','figcaption')}</figure></div></section>
<section class="letter" id="letter">{t('letterlabel','div','class="eyebrow"')}{t('letter','h2')}{t('letterbody','p')}</section>
<section class="program" id="programme"><div class="program-head">{t('program','h2')}{t('programnote','p')}</div>'''+''.join(f'<article class="event"><time>{time}</time>{t("p"+str(i),"h3")}{t("d"+str(i),"p")}</article>' for i,time in [(1,'21—22 / 10:00—18:00'),(2,'21 / 14:00—16:00'),(3,'22 / 12:00—13:00')])+f'''</section><section class="visit" id="visit">{t('visit','h2')}<div>{t('visitcopy','p')}{t('save','button','class="download" id="download"')}<p id="status" role="status"></p></div></section></main><footer>{t('footer')}{t('concept')}<button id="motion-toggle" aria-pressed="false">{en['pause']}</button></footer>'''
js='''let lang='en';const I18N=__I18N__;let paused=false;function apply(l){lang=l;document.documentElement.lang=l;document.documentElement.dataset.lang=l;document.querySelectorAll('[data-i18n]').forEach(e=>e.innerHTML=I18N[l][e.dataset.i18n]);document.querySelectorAll('button[data-lang]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.lang===l));document.querySelector('#motion-toggle').textContent=I18N[l][paused?'resume':'pause'];document.querySelector('#status').textContent='';}document.querySelectorAll('button[data-lang]').forEach(b=>b.onclick=()=>apply(b.dataset.lang));document.querySelector('#motion-toggle').onclick=()=>{paused=!paused;document.body.classList.toggle('motion-paused',paused);document.querySelector('#motion-toggle').setAttribute('aria-pressed',paused);document.querySelector('#motion-toggle').textContent=I18N[lang][paused?'resume':'pause'];};document.querySelector('#download').onclick=()=>{const d=I18N[lang];const text=['MARGINALIA — '+d.date,d.visitcopy,...[1,2,3].map(i=>d['p'+i]+'\n'+d['d'+i])].join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='marginalia-programme-'+lang+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#status').textContent=d.saved;};'''.replace('__I18N__',json.dumps({'en':en,'ru':ru},ensure_ascii=False))
# Python string literals must preserve JavaScript newline escapes.
js=js.replace("+'\n'+", "+'\\n'+").replace(".join('\n\n')", ".join('\\n\\n')")
license=(P.parents[2]/'motion-animation/motion_reference/originals/magic-ui/LICENSE.md').read_text()
